    # --- approved formulation content is immutable at the database level ---
    op.execute("""
        CREATE FUNCTION formulation_version_guard() RETURNS trigger AS $$
        BEGIN
            IF TG_OP = 'DELETE' THEN
                IF OLD.status <> 'DRAFT' THEN RAISE EXCEPTION 'formulation version % is % and cannot be deleted', OLD.id, OLD.status; END IF;
                RETURN OLD;
            END IF;
            IF OLD.status IN ('APPROVED','OBSOLETE') THEN
                IF NOT (OLD.status = 'APPROVED' AND NEW.status = 'OBSOLETE') AND NEW.status IS DISTINCT FROM OLD.status THEN
                    RAISE EXCEPTION 'formulation version % is % and cannot change status to %', OLD.id, OLD.status, NEW.status;
                END IF;
                IF NEW.batch_size IS DISTINCT FROM OLD.batch_size OR NEW.process_instructions IS DISTINCT FROM OLD.process_instructions
                   OR NEW.revision_note IS DISTINCT FROM OLD.revision_note OR NEW.formulation_id IS DISTINCT FROM OLD.formulation_id
                   OR NEW.version_no IS DISTINCT FROM OLD.version_no OR NEW.approved_by IS DISTINCT FROM OLD.approved_by
                   OR NEW.approved_at IS DISTINCT FROM OLD.approved_at OR NEW.effective_date IS DISTINCT FROM OLD.effective_date THEN
                    RAISE EXCEPTION 'approved formulation version % is immutable; create a new version', OLD.id;
                END IF;
            END IF;
            RETURN NEW;
        END; $$ LANGUAGE plpgsql;
    """)
